//! Small real public host controls; no daemon, GUI, fake source or private model.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_configuration;
use dmbc::{policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildRequest,BuildOutcome,Command},runner_host::BuildHost};
use std::path::{Path,PathBuf};
fn put(root:&Path,relative:&str,text:impl AsRef<[u8]>){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}
fn fixture(label:&str,full:bool)->PathBuf{let root=scratch::dir(label);put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(""));
 put(&root,"code/__defines/context.dm","#define CAPABILITIES(...)\n#define PROC_REF(P) #P\n/datum/act\n/datum/act/eval\n/obj/probe\n");
 put(&root,"code/structural.dm","/proc/leak(datum/act/A)\n    return list(A)\n/proc/allowed(datum/act/A)\n    return list(A) // ALLOW(handlers): preserve actual raw annotation consumption in native report\n");
 let mut manifest="#include \"code/__defines/context.dm\"\n#include \"code/structural.dm\"\n".to_owned();
 if full{put(&root,"code/handler.dm","/obj/probe/proc/handler(datum/act/eval/A)\n    return 2\nCAPABILITIES(/obj/probe,when(PROC_REF(handler)))\n");put(&root,"code/engine/present/protocols.dm","/datum/look\n/atom/proc/draw(datum/look/look)\n    return\n");put(&root,"code/output.dm","/obj/bad/draw(extra,datum/look/look)\n    return\n");manifest.push_str("#include \"code/handler.dm\"\n#include \"code/engine/present/protocols.dm\"\n#include \"code/output.dm\"\n");}
 put(&root,"deepquarry.dme",manifest);root}
fn request(root:&Path)->BuildRequest{let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual public preparation")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.timeout_seconds=Some(60);request.engine_template=None;request.bootstrap_catalog=false;request.cache_root=Some(root.join("cache"));request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.to_owned(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:vec![Q::SemHandlers],..Default::default()});request}
fn prepare(host:&mut BuildHost,request:&BuildRequest,full:bool)->BuildOutcome{let result=dmbc::request_runner::run_build_with_host(request.clone(),host).unwrap();let BuildOutcome::HandlersQueryPrepared{partial_source_revision:Some(_),full_source_revision,retained:true,..}=&result else{panic!("actual distinct partial subject outcome: {result:?}")};assert_eq!(full_source_revision.is_some(),full);assert!(host.symbolic_retention_stats().is_none_or(|stats|stats.records==0&&stats.successful_admissions==0&&stats.successful_reuses==0));assert!(!request.project.with_extension("dmb").exists());result}
fn report(host:&BuildHost,request:&BuildRequest,prepared:&BuildOutcome)->(String,Vec<(String,String,u32,String)>,usize){host.with_prepared_handlers_report_to(request,prepared,&mut Vec::new(),|data,config|{let empty=dq_analyze::scopes::LintScope::default();let scope=config.borrowed_report_scope(data.metadata().name,data.metadata().group).unwrap_or(&empty);let root=&request.policy_inputs.as_ref().unwrap().workspace.as_ref().unwrap().root;let finished=dq_analyze::policy_finish::finish_report(data.metadata(),scope,data,dq_analyze::lint::Run{sites:data.sites().to_vec(),notes:Vec::new()},data.allow_used().to_vec(),dq_analyze::policy_finish::Timing::default(),root,&None,true,|_,_,_|false,|_,_|false);Ok((finished.text,data.sites().iter().map(|s|(s.rule.clone(),s.rel.clone(),s.line,s.msg.clone())).collect(),data.allow_used().len()))}).unwrap()}
#[test]fn structural_partial_does_not_compile_unrequested_physical_dme_and_reuses_current_children(){let root=fixture("handlers-public-partial",false);std::fs::remove_file(root.join("deepquarry.dme")).unwrap();std::fs::create_dir(root.join("deepquarry.dme")).unwrap();let request=request(&root);let mut host=BuildHost::default();let cold=prepare(&mut host,&request,false);let actual=report(&host,&request,&cold);assert_eq!(actual.1.len(),1);assert_eq!(actual.1[0].0,"context_escape");assert_eq!(actual.2,1);assert_eq!(report(&host,&request,&cold),actual);let warm=prepare(&mut host,&request,false);assert_eq!(report(&host,&request,&warm),actual);assert!(request.project.is_dir(),"partial subject never installs or uses the physical DME as its TU root");}
#[test]fn whole_handler_current_report_contains_structural_declared_and_output_partitions(){let root=fixture("handlers-public-whole",true);let request=request(&root);let mut host=BuildHost::default();let prepared=prepare(&mut host,&request,true);let cold=report(&host,&request,&prepared);let rules=cold.1.iter().map(|s|s.0.as_str()).collect::<std::collections::BTreeSet<_>>();assert!(rules.contains("context_escape"));assert!(rules.contains("requirement_return"));assert!(rules.contains("output_signature"));assert_eq!(cold.2,1);assert_eq!(report(&host,&request,&prepared),cold);}
#[test]fn actual_handler_report_rejects_foreign_host_wrong_role_and_stale_preparation_before_callback(){let root=fixture("handlers-public-owner",false);let request=request(&root);let mut host=BuildHost::default();let prepared=prepare(&mut host,&request,false);let mut entered=false;let other=BuildHost::default();assert!(other.with_prepared_handlers_report(&request,&prepared,|_,_|{entered=true;Ok(())}).is_err());assert!(!entered);let mut wrong=request.clone();wrong.policy_inputs.as_mut().unwrap().workspace_auxiliary=vec![Q::DerivedReads];assert!(host.with_prepared_handlers_report(&wrong,&prepared,|_,_|{entered=true;Ok(())}).is_err());assert!(!entered);put(&root,"code/new.dm","/proc/new_escape(datum/act/A)\n    return list(A)\n");let current=prepare(&mut host,&request,false);assert!(host.with_prepared_handlers_report(&request,&prepared,|_,_|{entered=true;Ok(())}).is_err());assert!(!entered);assert_eq!(report(&host,&request,&current).1.len(),2);}
#[test]fn handler_configuration_failure_is_before_partial_or_full_source_and_recovery_is_genuine(){let root=fixture("handlers-public-config-first",false);put(&root,"tools/ci/lint_scopes.toml","[not valid TOML");std::fs::remove_file(root.join("deepquarry.dme")).unwrap();let request=request(&root);let mut host=BuildHost::default();let failure=dmbc::request_runner::run_build_with_host(request.clone(),&mut host).unwrap_err();assert!(failure.to_string().to_ascii_lowercase().contains("toml"));put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(""));let prepared=prepare(&mut host,&request,false);assert!(!report(&host,&request,&prepared).1.is_empty());}
#[test]fn current_handler_consumer_first_io_survives_then_same_source_report_recovers(){let root=fixture("handlers-public-first-error",true);let request=request(&root);let mut host=BuildHost::default();let prepared=prepare(&mut host,&request,true);let failure=host.with_prepared_handlers_report(&request,&prepared,|_,_|Err::<(),_>(std::io::Error::from_raw_os_error(1450))).unwrap_err();assert_eq!(failure.raw_os_error(),Some(1450));assert!(!report(&host,&request,&prepared).1.is_empty());}

#[path="support/handlers_actual_original_provider.rs"]mod actual_provider;
#[test]fn real_failed_full_open_keeps_structural_report_without_current_full_publication(){
 let root=fixture("handlers-public-real-full-failure",true);let request=request(&root);let mut host=BuildHost::default();let provider=actual_provider::source(true);let mut calls=0;
 let result=host.with_handlers_attempt_report_from_to(request.clone(),&provider,&mut Vec::new(),|data,_|{calls+=1;assert!(!data.sites().is_empty());assert!(data.sites().iter().all(|site|site.rule=="context_escape"),"genuine full-open failure skips only declared/output; not the authentic partial structural report");Ok(data.sites().len())}).unwrap();
 let failure=result.preparation.unwrap_err();assert_eq!(failure.downcast_ref::<std::io::Error>().map(std::io::Error::kind),Some(std::io::ErrorKind::NotFound));assert!(result.report.unwrap().unwrap()>0);assert_eq!(calls,1);assert!(host.symbolic_retention_stats().is_none_or(|stats|stats.records==0&&stats.successful_admissions==0&&stats.successful_reuses==0),"failed full source may retain its structural declarations but cannot lower executable bodies");assert!(provider.second_reads()>=2);
 let mut entered=false;let fake=BuildOutcome::HandlersQueryPrepared{query_revision:"0".into(),partial_source_revision:None,full_source_revision:None,retained:true};assert!(host.with_prepared_handlers_report(&request,&fake,|_,_|{entered=true;Ok(())}).is_err());assert!(!entered);
}
#[test]fn real_handler_source_failure_remains_first_separate_from_later_report_io(){
 let root=fixture("handlers-public-failed-first-source",true);let request=request(&root);let mut host=BuildHost::default();let provider=actual_provider::source(true);
 let result=host.with_handlers_attempt_report_from_to(request,&provider,&mut Vec::new(),|_,_|Err::<(),_>(std::io::Error::from_raw_os_error(1450))).unwrap();assert_eq!(result.preparation.unwrap_err().downcast_ref::<std::io::Error>().map(std::io::Error::kind),Some(std::io::ErrorKind::NotFound));assert_eq!(result.report.unwrap().unwrap_err().raw_os_error(),Some(1450));
}
